// The depth screen's model (web/src/screens/depth/model.ts, step S5) on the API's own answer for the research's saved
// chain reads of 2026-10-29 (test/fixtures/depth/api_depth_latest.json, generated by the minute job on the fixtures):
// the reading of a stored size, the when-not-to-act sentences computed from the answer (verify.txt C3: never typed),
// the ladder's bands read off the cumulative curves and held to the minute's own totals, the per-pool curves on the
// grid rebuilt from the reference price, the curve's marks and windows, the rewound reading of a stored minute, and (the
// phone cut) what the minute left out, grouped by reason.
// No test reaches the network.
import { describe, it, expect } from 'vitest';
import { depthFixture } from './depth-fixtures';
import { BANNED } from './banned-words';
import type { DepthHistoryResponse, DepthQuoteResponse, DepthResponse } from '../shared/depth';
import { CURVE_POOL_POINTS_MAX, DEPTH_SIZES, LADDER_FOLD_PCT, LADDER_MID_PCT, DEPTH_PAGE_WORDS, RESERVES_WORDS, bookBidUnder, cliffWords, marketWords, sellQuotable, bidQuotable } from '../shared/depth';
import { buildGrid, cumOn, thinIndices } from '../shared/depth-grid';
import { fmtNamRule, fmtSharePct, fmtSig, fmtUsdRule } from '../shared/format';
import {
  bookRule, cliffOf, cumToBand, curveWindow, depthStamp, isFar, isMid, ladderOf, marketSize, markedBand, overlap, parseAmount, perPoolCurves, pointAt, poolName, poolsAtPrice, priceRange, readingOfPoint, readingOfQuote, readingOfStored, routerLine, shortSize, sizeMarks, splitShares, storedFill, touchSpread, tradeMarks,
} from '../web/src/screens/depth/model';
import { FULL_RANGE, UNPRICED_EMPTY, UNPRICED_NO_PRICE, leftOutGroup, notReadWhy, pairUnnamed } from '../shared/depth';
import { leftOutGroups } from '../web/src/screens/depth/model';
import type { TradeRow } from '../shared/types';

const D = depthFixture<DepthResponse>('api_depth_latest.json');
const Q_SELL = depthFixture<DepthQuoteResponse>('api_depth_quote_sell_7300.json');
const Q_BUY = depthFixture<DepthQuoteResponse>('api_depth_quote_buy_7300.json');
const pct = (a: number, b: number) => Math.abs(a / b - 1) * 100;

describe('the reading', () => {
  it('a stored size is the minute’s own figure, with the minute’s stamp: 10,000 NAM sold fetches the prototype’s 9.924536 USD within five hundredths of a percent', () => {
    const r = readingOfStored(D, 'sell', 10_000)!;
    expect(r.kind).toBe('stored');
    expect(r.fill).toBe(storedFill(D, 'sell', 10_000));
    expect(pct(r.fill!.usd, 9.924536)).toBeLessThan(0.05);
    expect(r.vsRef).toBeLessThan(0);
    expect(r.stamp).toMatchObject({ at: D.at, height: D.ref.height, status: 'live', plain: 'Osmosis chain' });
    expect(readingOfStored(D, 'sell', 7300)).toBeNull();
    const shares = splitShares(r.fill!);
    expect(shares[0].pool).toBe('3005');
    expect(shares.reduce((a, s) => a + s.pct, 0)).toBeCloseTo(100, 3);
    expect(shares.every((s, i, a) => i === 0 || a[i - 1].nam >= s.nam)).toBe(true);
  });
  it('a quoted size carries the quote’s figures, its how and its reference; the quote for 7,300 sold sits between the stored 1,000 and 10,000', () => {
    const r = readingOfQuote(Q_SELL);
    expect(r.kind).toBe('quote');
    expect(r.nam).toBe(7300);
    expect(r.fill!.usd).toBeGreaterThan(storedFill(D, 'sell', 1000)!.usd);
    expect(r.fill!.usd).toBeLessThan(storedFill(D, 'sell', 10_000)!.usd);
    expect(r.how).toBe(Q_SELL.how);
    expect(r.stamp.at).toBe(D.at);
    const b = readingOfQuote(Q_BUY);
    expect(b.side).toBe('buy');
    expect(b.fill!.usd).toBeGreaterThan(r.fill!.usd);
  });
  it('the stamp reads old when the Worker says the minute is stale', () => {
    expect(depthStamp({ ...D, ref: { ...D.ref, status: 'stale' }, note: 'older' }).status).toBe('stale');
    expect(depthStamp(D).note).toBeUndefined();
  });
});

describe('when not to act, computed from the answer', () => {
  it('the cliff: the slice above 1,000 NAM moves the price far more than the slice below it, so the sentence names 1,000 and the two larger sizes with their average moves', () => {
    const c = cliffOf(D, 'sell')!;
    expect(c.above).toBe(1000);
    expect(c.a.nam).toBe(10_000);
    expect(c.b?.nam).toBe(100_000);
    expect(c.a.pct).toBeLessThan(0);
    expect(c.b!.pct).toBeLessThan(c.a.pct);
    const words = cliffWords('1,000', 'NAM', '10,000', `${c.a.pct.toFixed(1)}%`, '100,000', `${c.b!.pct.toFixed(1)}%`);
    expect(words).toMatch(/^Above the first 1,000 NAM each extra NAM fetches less: selling 10,000 averages -\d/);
    // buying: the first 1,000 cost less than the reference (pool 3009 sells under 3005's price), so the jump is read above 10,000
    expect(cliffOf(D, 'buy')!.above).toBe(10_000);
    expect(cliffOf(D, 'buy')!.a.nam).toBe(100_000);
    // no jump: a flat curve gives no sentence
    const flat = { ...D, answer: { ...D.answer, sell: D.answer.sell.map((f, i) => ({ ...f, usd: D.answer.sizes[i] * D.ref.usd * 0.999 })) } };
    expect(cliffOf(flat, 'sell')).toBeNull();
  });
  it('the book: its nearest bid is 65.6 % under the pool price after fees (the figure is measured against the after-fee price the sentence names, not the bare reference), so the sentence says to sell into the pools', () => {
    const b = bookRule(D)!;
    expect(b.bookId).toBe('3008');
    expect(b.underPct).toBeGreaterThan(60);
    expect(b.underPct).toBeLessThan(70);
    // the after-fee price is the reference less pool 3005's spread and the taker fee; the book's best bid is the fixture's 0.00035 under it
    const p3005 = D.pools.find((p) => p.id === '3005')!;
    expect(b.afterUsd).toBeCloseTo(D.ref.usd * (1 - p3005.spread - p3005.taker!), 12);
    expect(b.afterUsd).toBeLessThan(D.ref.usd);
    expect(pct(b.afterUsd * (1 - b.underPct / 100), 0.00035)).toBeLessThan(0.01);
    // against the bare reference the figure would read a tenth of a percent higher: the sentence says "after fees", so it does not
    expect(b.underPct).toBeLessThan((1 - 0.00035 / D.ref.usd) * 100);
    expect(bookBidUnder(`${b.underPct.toFixed(1)}%`, poolName(D, '3008'))).toContain('order book 3008’s nearest bid is 65.6% under');
    // a book whose bid is at the price: no sentence
    const near = { ...D, book: { levels: D.book.levels.map((l) => (l.pool === '3008' && l.side === 'bid' ? { ...l, loUsd: D.ref.usd, hiUsd: D.ref.usd } : l)) } };
    expect(bookRule(near)).toBeNull();
  });
  it('the market size: selling 10,000 NAM takes about two percent of the 507 USD of bids; buying measures against the coins resting on the ask side (1.7 million NAM), never the USD of the curve’s far tail, and a share that is not zero never prints as zero', () => {
    const m = marketSize(D, 'sell', storedFill(D, 'sell', 10_000))!;
    expect(m.total).toBe(D.within.totalBidUsd);
    expect(m.unit).toBe('usd');
    expect(m.share).toBeGreaterThan(1.5);
    expect(m.share).toBeLessThan(2.5);
    expect(marketWords('sell', fmtUsdRule(m.total), '10,000', 'NAM', fmtSharePct(m.share))).toBe('This is a $507.29 market on the bid side: selling 10,000 NAM takes 2% of it.');
    const b = marketSize(D, 'buy', storedFill(D, 'buy', 10_000))!;
    expect(b.unit).toBe('nam');
    expect(b.total).toBe(D.within.totalAskNam);
    expect(b.total).toBeGreaterThan(1_700_000);
    expect(b.total).toBeLessThan(1_800_000);
    // the ask curve's last point is the USD to buy every coin up to the grid's ceiling, two hundred thousand times the price: a million dollars that no one will pay
    expect(D.curve.askUsd[D.curve.askUsd.length - 1]).toBeGreaterThan(1_000_000);
    expect(b.total * D.ref.usd).toBeLessThan(D.curve.askUsd[D.curve.askUsd.length - 1] / 100);
    expect(b.share).toBeCloseTo((10_000 / D.within.totalAskNam) * 100, 9);
    expect(marketWords('buy', `${fmtNamRule(b.total)} NAM`, '10,000', 'NAM', fmtSharePct(b.share))).toBe('This is a 1,726,372 NAM market on the ask side: buying 10,000 NAM takes 0.58% of it.');
    const small = marketSize(D, 'buy', storedFill(D, 'buy', 1000))!;
    expect(fmtSharePct(small.share)).toBe('0.058%');
    expect(fmtSharePct(marketSize(D, 'buy', storedFill(D, 'buy', 1_000_000))!.share)).toBe('58%');
    expect(fmtSharePct(0.00096)).toBe('0.00096%');
    expect(fmtSharePct(0)).toBe('0%');
    expect(marketSize(D, 'sell', null)).toBeNull();
  });
  it('the router line is absent when the minute’s check was idle (the fixtures: no direct quote that minute)', () => {
    expect(D.checks.route).toBeNull();
    expect(routerLine(D)).toBeNull();
    const r = routerLine({ ...D, checks: { ...D.checks, route: { nam: 1000, routerOut: 1014160, ours: 1014160, diffPct: 0, at: D.at } } })!;
    expect(r).toMatchObject({ nam: 1000, routerUsd: 1.01416, oursUsd: 1.01416, diffPct: 0, pool: '3005' });
  });
});

describe('the per-pool curves on the rebuilt grid', () => {
  it('every pool’s thinned curve lands on the grid the Worker thinned (the shared grid code), the same count a pool, ascending through the reference; a pool with another count is left out', () => {
    const per = perPoolCurves(D);
    expect(per.size).toBe(Object.keys(D.curve.perPool).length);
    const grid = buildGrid(D.ref.usd);
    const idx = thinIndices(grid.length, grid.findIndex((g) => g >= D.ref.usd), CURVE_POOL_POINTS_MAX);
    for (const [, c] of per) {
      expect(c.price.length).toBe(idx.length);
      expect(c.price).toEqual(idx.map((i) => grid[i]));
      expect(c.price.some((p) => Math.abs(p / D.ref.usd - 1) < 1e-9)).toBe(true);
    }
    const agg = thinIndices(grid.length, grid.findIndex((g) => g >= D.ref.usd), 400).map((i) => grid[i]);
    expect(agg.length).toBe(D.curve.price.length);
    agg.forEach((p, k) => expect(pct(p, D.curve.price[k])).toBeLessThan(1e-3));
    const bad = { ...D, curve: { ...D.curve, perPool: { ...D.curve.perPool, '3005': { bidUsd: [1, 2, 3], askUsd: [1, 2, 3] } } } };
    expect(perPoolCurves(bad).has('3005')).toBe(false);
  });
});

describe('a level’s share of a band', () => {
  it('a range by price width, a point level (a book order) whole when inside, nothing outside', () => {
    expect(overlap({ loUsd: 1, hiUsd: 3 }, 2, 4)).toBeCloseTo(0.5, 12);
    expect(overlap({ loUsd: 1, hiUsd: 3 }, 0, 10)).toBe(1);
    expect(overlap({ loUsd: 1, hiUsd: 3 }, 3, 4)).toBe(0);
    expect(overlap({ loUsd: 2, hiUsd: 2 }, 2, 3)).toBe(1);
    expect(overlap({ loUsd: 3, hiUsd: 3 }, 2, 3)).toBe(0);
  });
});

describe('the ladder', () => {
  const L = ladderOf(D, 1);
  it('asks above (furthest first), bids below (nearest first), the nearest band on each side starting at the reference, and the bands’ totals equal to the minute’s own within a percent', () => {
    expect(L.asks.length).toBeGreaterThan(100);
    expect(L.bids.length).toBeGreaterThan(50);
    expect(L.asks[L.asks.length - 1].lo).toBeCloseTo(D.ref.usd, 12);
    expect(L.bids[0].hi).toBeCloseTo(D.ref.usd, 12);
    for (let i = 1; i < L.asks.length; i++) expect(L.asks[i].hi).toBeLessThanOrEqual(L.asks[i - 1].lo + 1e-12);
    for (let i = 1; i < L.bids.length; i++) expect(L.bids[i].hi).toBeLessThanOrEqual(L.bids[i - 1].lo + 1e-12);
    expect(pct(L.bids.reduce((a, b) => a + b.usd, 0), D.within.totalBidUsd)).toBeLessThan(1);
    expect(pct(L.asks.reduce((a, b) => a + b.nam, 0), D.within.totalAskNam)).toBeLessThan(1);
    expect(L.maxCumBid).toBeCloseTo(L.bids[L.bids.length - 1].cum, 9);
    expect(L.maxCumAsk).toBeCloseTo(L.asks[0].cum, 9);
    // the bands down to a price hold what the curve holds down to it (the bands telescope), and about what the minute stored as within ten percent
    const near = L.bids.filter((b) => b.lo >= D.ref.usd * 0.9);
    const bid10 = near.reduce((a, b) => a + b.usd, 0);
    expect(pct(bid10, cumOn(D.curve.price, D.curve.bidUsd, near[near.length - 1].lo))).toBeLessThan(0.1);
    expect(pct(bid10, D.within.bidUsd10)).toBeLessThan(10);
  });
  it('each band names its pools as shares of the band’s own figure (they sum to it), from the minute’s raw levels; the book’s bands count orders, a concentrated pool’s its tick ranges, a weighted pool is read from its reserves and counts neither', () => {
    for (const b of [...L.asks.slice(-5), ...L.bids.slice(0, 5)]) {
      expect(b.pools.length).toBeGreaterThan(0);
      expect(b.pools.reduce((a, p) => a + p.usd, 0)).toBeCloseTo(b.usd, 9);
      expect(b.pools.reduce((a, p) => a + p.nam, 0)).toBeCloseTo(b.nam, 9);
      expect(b.pools.every((p, i, a) => i === 0 || a[i - 1].usd >= p.usd)).toBe(true);
      expect(b.pools[0].feePct).toBeGreaterThanOrEqual(0);
    }
    const near = L.bids[0];
    expect(near.pools[0].id).toBe('3005');
    expect(near.pools[0].ranges).toBeGreaterThan(0);
    expect(near.pools[0].kind).toBe('ranges');
    const bookBand = L.bids.find((b) => b.pools.some((p) => p.id === '3008'))!;
    expect(bookBand).toBeDefined();
    expect(bookBand.pools.find((p) => p.id === '3008')!.orders).toBeGreaterThan(0);
    expect(bookBand.pools.find((p) => p.id === '3008')!.kind).toBe('orders');
    expect(bookBand.pools.find((p) => p.id === '3008')!.feePct).toBe(0);
    // a weighted (balancer) pool holds its reserves at one point: no tick range is counted for it, and the sheet says "from its reserves"
    const weighted = D.pools.filter((p) => p.type === 'balancer' || p.type === 'stableswap');
    expect(weighted.length).toBeGreaterThan(0);
    const inBands = [...L.asks, ...L.bids].flatMap((b) => b.pools).filter((p) => p.type === 'balancer' || p.type === 'stableswap');
    expect(inBands.length).toBeGreaterThan(0);
    for (const p of inBands) { expect(p.kind).toBe('reserves'); expect(p.ranges).toBe(0); expect(p.orders).toBe(0); }
    for (const p of [...L.asks, ...L.bids].flatMap((b) => b.pools).filter((p) => p.type === 'concentrated')) expect(p.kind).toBe('ranges');
    expect(RESERVES_WORDS).toBe('from its reserves');
  });
  it('the folds: rows further than 50 % are far, rows between 10 % and 50 % are mid; the three widths give more rows the narrower they are', () => {
    expect(L.asks.filter(isFar).every((b) => b.dist > LADDER_FOLD_PCT)).toBe(true);
    expect(L.asks.filter(isMid).every((b) => b.dist > LADDER_MID_PCT && b.dist <= LADDER_FOLD_PCT)).toBe(true);
    expect(L.asks.filter((b) => !isFar(b) && !isMid(b)).length).toBe(L.asks.filter((b) => b.dist <= LADDER_MID_PCT).length);
    const half = ladderOf(D, 0.5), wide = ladderOf(D, 2.5);
    expect(half.bids.length).toBeGreaterThan(L.bids.length);
    expect(wide.bids.length).toBeLessThan(L.bids.length);
    expect(pct(half.bids.reduce((a, b) => a + b.usd, 0), wide.bids.reduce((a, b) => a + b.usd, 0))).toBeLessThan(1);
  });
  it('the marked band holds the picked size’s marginal price; selling down to a bid band’s far edge is the curve’s own figure there', () => {
    const r = readingOfStored(D, 'sell', 10_000)!;
    const m = markedBand(L, r)!;
    expect(m.side).toBe('bid');
    expect(m.lo).toBeLessThanOrEqual(r.fill!.marginalPrice);
    expect(m.hi).toBeGreaterThan(r.fill!.marginalPrice);
    expect(cumToBand(D, m)).toBeCloseTo(cumOn(D.curve.price, D.curve.bidUsd, m.lo), 12);
    expect(cumToBand(D, m)).toBeGreaterThanOrEqual(r.fill!.usd * 0.99);
    expect(markedBand(L, readingOfStored(D, 'buy', 1000))!.side).toBe('ask');
    expect(markedBand(L, null)).toBeNull();
  });
  it('the reference row: the best bid and ask for 100 NAM after fees, crossed across pools on these fixtures (3009 sells cheaper than 3005 buys)', () => {
    const s = touchSpread(D)!;
    expect(s).toBeLessThan(0);
    expect(D.touch.bestAskPool).toBe('3009');
    expect(D.touch.bestBidPool).toBe('3005');
  });
});

describe('the curve', () => {
  it('eight size marks, one per stored fill each way, each at its marginal price with its USD', () => {
    const marks = sizeMarks(D);
    expect(marks.length).toBe(DEPTH_SIZES.length * 2);
    for (const m of marks) {
      const f = storedFill(D, m.side, m.nam)!;
      expect(m.price).toBe(f.marginalPrice);
      expect(m.usd).toBe(f.usd);
      if (m.side === 'sell') expect(m.price).toBeLessThan(D.ref.usd); else expect(m.price).toBeGreaterThan(D.ref.usd);
    }
  });
  it('the windows: near is linear from half to twice the reference, wide and all are log and said so', () => {
    expect(curveWindow(D, 'near')).toEqual({ lo: D.ref.usd / 2, hi: D.ref.usd * 2, log: false });
    expect(curveWindow(D, 'wide')).toEqual({ lo: D.ref.usd / 10, hi: D.ref.usd * 10, log: true });
    const all = curveWindow(D, 'all');
    expect(all.log).toBe(true);
    expect(all.lo).toBe(D.curve.price[0]);
    expect(all.hi).toBe(D.curve.price[D.curve.price.length - 1]);
  });
  it('the pools at a price: just under the reference, pool 3005 holds the most; at the book’s bid, the order book', () => {
    const per = perPoolCurves(D);
    expect(poolsAtPrice(D, per, 'bid', D.ref.usd * 0.99)[0]).toBe('3005');
    expect(poolsAtPrice(D, per, 'ask', D.ref.usd * 1.01).length).toBeGreaterThan(0);
    expect(poolsAtPrice(D, per, 'bid', 0.00035)).toContain('3008');
    // far under the price only the ranges that start at zero and the weighted pools remain; the book has no bid there
    expect(poolsAtPrice(D, per, 'bid', 1e-8)).not.toContain('3008');
  });
  it('the trade marks: a trade with a settle price sits at it with its value; one with a recorded price but no settle at that; one with neither is left out, as is one before the window', () => {
    const base: TradeRow = { id: 'a', ts: 1_000_000, height: 1, tsSource: 'block', kind: 'sell', nam: 1000, counterSymbol: 'USDC', counterAmount: 1, priceUsd: 0.001, priceSource: 'execution', valueUsd: 1, maker: null, makerLabelPlain: null, makerTrades: null, route: ['3005'], txHash: 'X', pattern: null };
    const rows: TradeRow[] = [
      { ...base, id: 'settled', settle: { side: 'sell', usdPerNam: 0.00098, nam: 1000, coins: [], gasUsd: null, gasLeftOut: false } },
      { ...base, id: 'priced', priceUsd: 0.00101, valueUsd: 1.01 },
      { ...base, id: 'none', priceUsd: null, valueUsd: null, priceSource: null },
      { ...base, id: 'old', ts: 10 },
    ];
    const m = tradeMarks(rows, 100);
    expect(m.map((x) => x.id)).toEqual(['settled', 'priced']);
    expect(m[0].price).toBe(0.00098);
    expect(m[0].usd).toBeCloseTo(0.98, 9);
    expect(m[1].price).toBe(0.00101);
    expect(m[1].usd).toBe(1.01);
  });
});

describe('rewound: the stored minute', () => {
  const pt = { t: D.at, at: D.at + 30_000, height: D.ref.height, refUsd: D.ref.usd, spotUsd: null, bid: D.offsets.bid, ask: D.offsets.ask, sell: D.answer.sell.map((f) => f.usd), buy: D.answer.buy.map((f) => f.usd), bestBid: D.touch.bestBidEff, bestAsk: D.touch.bestAskEff, bidUsd: D.within.totalBidUsd, askNam: D.within.totalAskNam, note: null };
  const h: DepthHistoryResponse = { pool: 'all', refPool: '3005', step: '1m', from: D.at - 600_000, to: D.at + 1, asOf: D.at + 1, points: [{ ...pt, t: D.at - 60_000, at: D.at - 30_000 }, pt], gaps: [], start: D.at - 600_000, recordedSince: D.at - 600_000, cut: false, note: null, prov: [] };
  it('the newest point at or before the moment is read; its figure for a stored size is the minute’s, the split empty and the marginal not stored', () => {
    expect(pointAt(h, D.at + 20_000)).toBe(h.points[1]);
    expect(pointAt(h, D.at - 1)).toBe(h.points[0]);
    expect(pointAt(h, D.at - 120_000)).toBeNull();
    expect(pointAt(null, D.at)).toBeNull();
    const r = readingOfPoint(pt, 'sell', 10_000, DEPTH_SIZES, 'the stored minute of 02:56 UTC')!;
    expect(r.kind).toBe('past');
    expect(r.fill!.usd).toBe(storedFill(D, 'sell', 10_000)!.usd);
    expect(r.fill!.split).toEqual([]);
    expect(Number.isNaN(r.fill!.marginalPrice)).toBe(true);
    expect(r.stamp.at).toBe(pt.at);
    expect(readingOfPoint(pt, 'sell', 7300, DEPTH_SIZES, '')).toBeNull();
    const none = readingOfPoint({ ...pt, sell: [null, null, null, null], note: 'the pool was not read' }, 'sell', 10_000, DEPTH_SIZES, '')!;
    expect(none.kind).toBe('none');
    expect(none.reason).toBe('the pool was not read');
  });
});

describe('the words and the small helpers', () => {
  it('prices at significant digits, never a fixed six decimals; sizes short; amounts parsed', () => {
    expect(fmtSig(D.ref.usd)).toBe('0.0010199');
    expect(fmtSig(198.57)).toBe('198.57');
    expect(fmtSig(0.00035)).toBe('0.00035');
    expect(fmtSig(0)).toBe('0');
    expect(fmtSig(null)).toBe('—');
    expect([1000, 10_000, 100_000, 1_000_000].map(shortSize)).toEqual(['1k', '10k', '100k', '1M']);
    expect(parseAmount('7,300')).toBe(7300);
    expect(parseAmount('12.5')).toBe(12.5);
    expect(parseAmount('x')).toBeNull();
    expect(parseAmount('0')).toBeNull();
  });
  it('the page’s sentences carry no banned word and only the figures passed in; the two quotable lines read as the plan wrote them', () => {
    for (const w of DEPTH_PAGE_WORDS) expect(w, w).not.toMatch(BANNED);
    expect(sellQuotable('10,000', 'NAM', '$9.92')).toBe('Selling 10,000 NAM now fetches $9.92 across every Osmosis pool');
    expect(bidQuotable('$26.43', '10%')).toBe('$26.43 of bids within 10% of the price');
    expect(sellQuotable('10,000', 'NAM', '$9.92').match(/\d[\d,.]*/g)).toEqual(['10,000', '9.92']);
  });
});

describe('a position’s range in words (step S6)', () => {
  it('two prices at significant digits; a position spanning every price the pool can reach (the chain’s own extremes) is the whole range, never two unreadable figures', () => {
    expect(priceRange(0.000902, 0.000923)).toBe('0.000902 – 0.000923');
    expect(priceRange(1e-12, 1e38)).toBe(FULL_RANGE);
    expect(priceRange(null, 0.001)).toBe('— – 0.001');
  });
});

describe('what the minute left out, grouped by reason (the phone cut, owner 2026-10-30)', () => {
  it('the fixture’s thirteen pools are three reasons, each once with its count, in the order the minute lists them; a raw denomination is named in words and an empty pool without its pair', () => {
    const g = leftOutGroups(D, 'NAM');
    expect(g.map((x) => x.why)).toEqual([...new Set(D.unpriced.map((u) => u.why))]);
    expect(g[0].words).toBe(leftOutGroup(1, UNPRICED_NO_PRICE, 'pool 3020 (NAM / UM)'));
    const dust = g.find((x) => x.words.startsWith('10 pools, each: holds under'))!;
    expect(dust.words).toContain(`pool 3018 (${pairUnnamed('NAM')})`);
    expect(dust.words).toContain('pool 3010 (NAM / USDC)');
    expect(g.find((x) => x.why === UNPRICED_EMPTY)!.words).toBe(leftOutGroup(2, UNPRICED_EMPTY, 'pool 3016, pool 3021'));
    for (const x of g) expect(x.words).not.toMatch(/ibc\/|factory\//);
  });
  it('pools not read are grouped by their own failure text, after the unpriced ones', () => {
    const pools = D.pools.slice(0, 3).map((p, i) => ({ ...p, read: { error: i < 2 ? 'status 429' : 'timed out' } })) as unknown as DepthResponse['pools'];
    const g = leftOutGroups({ unpriced: [], pools }, 'NAM');
    expect(g.map((x) => x.why)).toEqual([notReadWhy('status 429'), notReadWhy('timed out')]);
    expect(g[0].words.startsWith(`2 pools, each: ${notReadWhy('status 429')}: `)).toBe(true);
    expect(g[1].words.startsWith(`1 pool: ${notReadWhy('timed out')}: `)).toBe(true);
  });
});
